const mkClip=(a,b,extra)=>Object.assign({id:uid('c'),name:'',in:+a.toFixed(3),out:+b.toFixed(3),desc:'',sugg:'',thumb:'',adj:{exp:0,con:0,sat:0,temp:0},frame:{scale:1,x:0,y:0},fx:{look:'none',vignette:0,blur:0},speed:1,vol:1,mute:false,fadeIn:0,fadeOut:0,trans:{type:'none',dur:0.4},status:'ok'},extra||{});

// ---------- media ----------
async function srcURL(p){if(LOCAL[p.id])return LOCAL[p.id];if(p.src.url)return p.src.url;return null}
function mkVideo(url){const v=document.createElement('video');v.playsInline=true;v.preload='auto';if(!/^blob:/.test(url))v.crossOrigin='anonymous';v.src=url;return v}
const seekTo=(v,t)=>new Promise(r=>{if(!v||!isFinite(t))return r();if(Math.abs(v.currentTime-t)<0.012&&v.readyState>=2)return r();let done=false;const f=()=>{if(done)return;done=true;v.removeEventListener('seeked',f);r()};v.addEventListener('seeked',f);try{v.currentTime=Math.max(0,t)}catch(e){f()}setTimeout(f,2500)});
const ready=v=>new Promise(r=>{if(v.readyState>=1)return r();v.addEventListener('loadedmetadata',()=>r(),{once:true});v.addEventListener('error',()=>r(),{once:true});setTimeout(r,15000)});
const trackURL=tr=>LOCALA[tr.id]||tr.url||'';
function imgOf(src){if(!src)return null;if(src.startsWith('logo:')){const k=src.slice(5);if(!LOGOS[k])return null;src='data:image/png;base64,'+(LOGOS[k].b64||LOGOS[k])}if(IMG[src])return IMG[src];const i=new Image();if(!/^(data|blob):/.test(src))i.crossOrigin='anonymous';i.onload=()=>{paint();drawTL()};i.src=src;IMG[src]=i;return i}

// ---------- analysis ----------
async function analyze(p){const url=await srcURL(p);if(!url)throw new Error('הקובץ של הסרטון לא נמצא במכשיר הזה. בחרו אותו שוב');
  S.busy={t:'קורא את הסרטון',pct:0};paintBusy();const v=mkVideo(url);v.muted=true;await ready(v);if(!v.duration||!isFinite(v.duration))throw new Error('הדפדפן לא הצליח לקרוא את הסרטון. נסו קובץ MP4 או MOV');
  p.meta.dur=v.duration;p.meta.w=v.videoWidth;p.meta.h=v.videoHeight;
  const dur=v.duration,step=dur<=60?0.25:dur<=300?0.5:Math.max(1,dur/600);const cw=48,ch=27;const cv=document.createElement('canvas');cv.width=cw;cv.height=ch;const x=cv.getContext('2d',{willReadFrequently:true});
  const tc=document.createElement('canvas');tc.width=160;tc.height=Math.max(60,Math.round(160*(v.videoHeight||9)/(v.videoWidth||16)));const tx=tc.getContext('2d');const diffs=[],thumbs={};let prev=null,tainted=false;
  for(let t=0,n=0;t<dur-0.05;t+=step,n++){await seekTo(v,t);S.busy={t:'מזהה סצנות',pct:t/dur};paintBusy();x.drawImage(v,0,0,cw,ch);let d;try{d=x.getImageData(0,0,cw,ch).data}catch(e){tainted=true;break}
    const g=new Float32Array(cw*ch);for(let i=0;i<g.length;i++)g[i]=(d[i*4]*.299+d[i*4+1]*.587+d[i*4+2]*.114)/255;if(prev){let s=0;for(let i=0;i<g.length;i++)s+=Math.abs(g[i]-prev[i]);diffs.push({t,d:s/g.length})}prev=g;
    if(n%Math.max(1,Math.round(1/step))===0){tx.drawImage(v,0,0,tc.width,tc.height);thumbs[t.toFixed(2)]=tc.toDataURL('image/jpeg',.6)}}
  // a cut is a local peak well above the footage's own motion (the median change) and above its neighbourhood
  let cuts=[];if(!tainted&&diffs.length>4){const ds=diffs.map(o=>o.d);const med=[...ds].sort((a,b)=>a-b)[Math.floor(ds.length/2)];let thr=Math.max(0.045,med*3.5);const near=i=>{const w=ds.slice(Math.max(0,i-4),i).concat(ds.slice(i+1,i+5)).sort((a,b)=>a-b);return w.length?w[Math.floor(w.length/2)]:0};
    for(let k=0;k<8;k++){cuts=diffs.filter((o,i)=>o.d>thr&&o.d>2.2*near(i)&&(i===0||o.d>=ds[i-1])&&(i===ds.length-1||o.d>=ds[i+1])).map(o=>o.t);if(cuts.length<=60)break;thr*=1.25}}
  const bounds=[0,...cuts,dur];const raw=[];for(let i=0;i<bounds.length-1;i++){const a=bounds[i],b=bounds[i+1];if(raw.length&&b-a<0.8)raw[raw.length-1].out=b;else raw.push({in:a,out:b})}if(raw.length>1&&raw[raw.length-1].out-raw[raw.length-1].in<0.8){const l=raw.pop();raw[raw.length-1].out=l.out}
  const nearT=t=>{let best='',bd=1e9;Object.keys(thumbs).forEach(k=>{const dd=Math.abs(+k-t-0.3);if(dd<bd){bd=dd;best=k}});return thumbs[best]||''};
  p.clips=raw.map((r,i)=>mkClip(r.in,r.out,{name:'סצנה '+(i+1),thumb:nearT(r.in)}));if(tainted)p.note='הסרטון מוגש משרת אחר בלי הרשאה לקרוא פיקסלים, אז הוא נכנס כקטע אחד';
  S.busy={t:'קורא את השמע',pct:0};paintBusy();try{await audio(p,url)}catch(e){p.meta.hasAudio=false}
  p.base=clone(core(p));p.status='ready';logOp({kind:'import',instr:'ייבוא וזיהוי סצנות',status:'auto',result:`${p.clips.length} סצנות, ${fmt(dur)}`});S.busy=null;persist(p)}
async function decode(url){const r=await fetch(url);const size=+(r.headers.get('content-length')||0);if(size>400*1024*1024)throw new Error('big');const buf=await r.arrayBuffer();const AC=window.AudioContext||window.webkitAudioContext;const ac=new AC();let ab;try{ab=await ac.decodeAudioData(buf.slice(0))}finally{try{ac.close()}catch(x){}}
  const sr=16000,n=Math.max(1,Math.ceil(ab.duration*sr));const oc=new OfflineAudioContext(1,n,sr);const s=oc.createBufferSource();s.buffer=ab;s.connect(oc.destination);s.start();const out=await oc.startRendering();const data=out.getChannelData(0);
  const hop=sr/20,peaks=new Float32Array(Math.ceil(data.length/hop));for(let i=0;i<peaks.length;i++){let m=0;for(let j=i*hop,e=Math.min(data.length,(i+1)*hop);j<e;j++){const a=Math.abs(data[j]);if(a>m)m=a}peaks[i]=m}let mx=0;for(const v of peaks)if(v>mx)mx=v;return {sr,data,peaks,mx:mx||1,dur:ab.duration}}
async function audio(p,url){if(AUD[p.id])return AUD[p.id];let A;try{A=await decode(url)}catch(e){p.meta.hasAudio=false;return null}p.meta.hasAudio=A.mx>0.003;AUD[p.id]=A;return A}
function gaps(p,a,b,min){const A=AUD[p.id];if(!A)return null;const sr=A.sr,w=sr/50;const i0=Math.floor(a*sr),i1=Math.min(A.data.length,Math.floor(b*sr));const rms=[];for(let i=i0;i<i1;i+=w){let s=0;for(let j=i;j<Math.min(i1,i+w);j++)s+=A.data[j]*A.data[j];rms.push(Math.sqrt(s/w))}
  if(!rms.length)return [];const sorted=[...rms].sort((x,y)=>x-y);const speech=sorted[Math.floor(sorted.length*0.9)]||0;const thr=Math.max(0.004,speech*0.12);const out=[];let st=-1;rms.forEach((v,k)=>{if(v<thr){if(st<0)st=k}else if(st>=0){if((k-st)/50>=min)out.push([a+st/50,a+k/50]);st=-1}});if(st>=0&&(rms.length-st)/50>=min)out.push([a+st/50,a+rms.length/50]);return out}
// where a new audio file lines up with the original sound: cross correlation of 50 Hz loudness envelopes, up to ±30 s
function syncOffset(A,B){const env=X=>{const w=X.sr/50,n=Math.floor(X.data.length/w),e=new Float32Array(n);for(let i=0;i<n;i++){let s=0;for(let j=i*w;j<(i+1)*w;j++)s+=Math.abs(X.data[j]);e[i]=s/w}let m=0;for(const v of e)m+=v;m/=n||1;for(let i=0;i<n;i++)e[i]-=m;return e};
  const a=env(A),b=env(B);let best=0,bv=-1e9;const R=Math.min(1500,Math.max(a.length,b.length));for(let lag=-R;lag<=R;lag++){let s=0;for(let i=0;i<b.length;i++){const j=i+lag;if(j>=0&&j<a.length)s+=a[j]*b[i]}if(s>bv){bv=s;best=lag}}return {sec:best/50,score:bv}}

// ---------- the compositor: one function for the preview and the export ----------
function outDims(p,max){const w=p.meta.w||1080,h=p.meta.h||1920;const r={'9:16':[9,16],'16:9':[16,9],'1:1':[1,1],'4:5':[4,5]}[p.fmt];let W,H;if(!r){W=w;H=h}else{if(r[0]/r[1]>w/h){W=w;H=Math.round(w*r[1]/r[0])}else{H=h;W=Math.round(h*r[0]/r[1])}}const m=max||Math.max(W,H);const k=Math.min(1,m/Math.max(W,H));return [Math.round(W*k/2)*2,Math.round(H*k/2)*2]}
function vfilter(c){const a=c.adj;const lk=(LOOKS.find(l=>l[0]===c.fx.look)||[])[2]||'';return `${lk} brightness(${(1+a.exp*0.6).toFixed(3)}) contrast(${(1+a.con*0.8).toFixed(3)}) saturate(${Math.max(0,1+a.sat).toFixed(3)})${c.fx.blur>0?` blur(${(c.fx.blur).toFixed(1)}px)`:''}`.trim()}
