    if(L.shape==='rect'){rr(c,-bw/2,-bh/2,bw,bh,Math.min(bw,bh)*(L.radius||0));if(L.fill)c.fill();if(L.stroke)c.stroke()}else if(L.shape==='circle'){c.beginPath();c.ellipse(0,0,bw/2,bh/2,0,0,7);if(L.fill)c.fill();if(L.stroke)c.stroke()}
