// audio tracks: one element per clip, kept in step with the timeline; ducking lowers music while someone speaks
function Mixer(opt){opt=opt||{};const M={};const self={};
  const key=(tr,c)=>tr.id+'/'+c.id;
  function el(tr,c){const k=key(tr,c);if(M[k])return M[k];const u=trackURL(tr);if(!u)return null;const a=new Audio();if(!/^(blob|data):/.test(u))a.crossOrigin='anonymous';a.preload='auto';a.src=u;const r={a,g:null};if(opt.dest){const s=opt.ac.createMediaElementSource(a),g=opt.ac.createGain();s.connect(g);g.connect(opt.dest);r.g=g}M[k]=r;return r}
  const speech=(p,t)=>{const a=at(t,p);if(a&&p.subs.segs.length){const st=srcT(a.x.c,a.local);if(p.subs.segs.some(g=>st>=g.t0&&st<g.t1))return true}return p.tracks.some(tr=>tr.kind==='narration'&&!tr.mute&&tr.clips.some(c=>t>=c.start&&t<c.start+(c.out-c.in)))};
  self.gain=(p,tr,c,t,talk)=>{const solo=p.tracks.some(x=>x.solo)||p.orig.solo;const d=c.out-c.in;let g=(tr.mute||c.mute||(solo&&!tr.solo))?0:c.vol*tr.vol;const u=t-c.start,o=d-u;if(c.fadeIn>0&&u<c.fadeIn)g*=u/c.fadeIn;if(c.fadeOut>0&&o<c.fadeOut)g*=Math.max(0,o/c.fadeOut);if(tr.duck&&tr.kind==='music'&&talk)g*=0.3;return g};
  self.sync=(p,t,playing)=>{const talk=speech(p,t);const live=new Set();
    p.tracks.forEach(tr=>tr.clips.forEach(c=>{const d=c.out-c.in;const on=playing&&t>=c.start&&t<c.start+d;const r=on?el(tr,c):M[key(tr,c)];if(!r)return;live.add(key(tr,c));
      if(!on){if(!r.a.paused)r.a.pause();return}const want=c.in+(t-c.start);if(r.a.paused){try{r.a.currentTime=want}catch(e){}r.a.play().catch(()=>{})}else if(Math.abs(r.a.currentTime-want)>0.25){try{r.a.currentTime=want}catch(e){}}
      const g=self.gain(p,tr,c,t,talk);if(r.g)r.g.gain.value=g;else r.a.volume=clamp(g,0,1)}));Object.keys(M).forEach(k=>{if(!live.has(k)&&!M[k].a.paused)M[k].a.pause()})};
  self.stop=()=>Object.values(M).forEach(r=>{try{r.a.pause()}catch(e){}});self.destroy=()=>{self.stop();Object.values(M).forEach(r=>{r.a.removeAttribute('src')})};self.M=M;return self}

// ---------- preview ----------
let PL=null,PLurl='',MX=null;
async function ensurePlayer(){const p=S.p;if(!p)return null;const url=await srcURL(p);if(!url)return null;if(PL&&PLurl===url)return PL;if(PL)PL.destroy();PL=Player(url,{rate:S.rate});PLurl=url;await ready(PL.els[0]);return PL}
const cvs=()=>document.querySelector('.v205 canvas.v205cv');
function paint(){const cv=cvs();const p=P();if(!cv||!p||!PL)return;const [W,H]=outDims(p,1280);if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H}compose(cv.getContext('2d'),W,H,p,PL,S.t,{compare:S.compare,boxes:true,ghostSubs:true});const tl=$('v205tc');if(tl)tl.textContent=fmt(S.t)+' / '+fmt(lay(p).total);overlay();playhead()}
async function seek(t){const p=P();if(!p)return;S.t=clamp(t,0,lay(p).total);if(S.playing)stopPlay();const pl=await ensurePlayer();if(!pl)return;await pl.seek(p,S.t);paint();markCur()}
async function playToggle(){if(S.playing){stopPlay();return}const p=P();const pl=await ensurePlayer();if(!pl)return;if(S.t>=lay(p).total-0.05)S.t=0;await pl.seek(p,S.t);S.playing=true;pl.rate(S.rate);if(!MX)MX=Mixer();btnPlay();
  pl.play(p,{onFrame:t=>{S.t=t;MX.sync(P(),t,true);paint();const a=at(t,p);if(a&&a.x.c.id!==S.curPlay){S.curPlay=a.x.c.id;markCur(a.x.c.id)}},onEnd:()=>{S.playing=false;MX&&MX.stop();btnPlay()}})}
function stopPlay(){S.playing=false;if(PL)PL.stop();if(MX)MX.stop();btnPlay()}
function btnPlay(){const b=document.querySelector('.v205 [data-v204="play"]');if(b){b.textContent=S.playing?'❚❚':'▶';b.setAttribute('aria-label',S.playing?'השהיה':'ניגון')}}
function markCur(id){id=id||S.cur;document.querySelectorAll('.v205 .v204sc').forEach(e=>e.classList.toggle('now',e.dataset.id===id))}

// ---------- direct manipulation on the canvas ----------
const objLayer=()=>S.obj&&S.obj!=='__subs'&&P()?P().layers.find(l=>l.id===S.obj):null;
function canvasRect(){const cv=cvs();if(!cv)return null;const r=cv.getBoundingClientRect();return r.width?r:null}
function overlay(){const ov=$('v205ov');const r=canvasRect();const host=document.querySelector('.v205stg');if(!ov||!r||!host)return;const hr=host.getBoundingClientRect();Object.assign(ov.style,{left:(r.left-hr.left)+'px',top:(r.top-hr.top)+'px',width:r.width+'px',height:r.height+'px'});
  const sel=ov.querySelector('.v205sel');const b=S.obj&&BOX[S.obj];if(!b){sel.hidden=true;return}const L=objLayer();sel.hidden=false;sel.classList.toggle('lock',!!(L&&L.locked));sel.classList.toggle('subs',S.obj==='__subs');sel.setAttribute('aria-label','נבחר: '+(L?L.name:'כתוביות'));
  Object.assign(sel.style,{left:(b.cx*r.width)+'px',top:(b.cy*r.height)+'px',width:Math.max(8,b.w*r.width)+'px',height:Math.max(8,b.h*r.height)+'px',transform:`translate(-50%,-50%) rotate(${b.rot||0}deg)`})}
function guides(gx,gy){const ov=$('v205ov');if(!ov)return;ov.querySelectorAll('.v205g').forEach(g=>g.remove());(gx||[]).forEach(x=>{const d=document.createElement('i');d.className='v205g v';d.style.left=(x*100)+'%';ov.appendChild(d)});(gy||[]).forEach(y=>{const d=document.createElement('i');d.className='v205g h';d.style.top=(y*100)+'%';ov.appendChild(d)})}
function hitObj(u,v){const p=P();const ids=[...(p.layers||[])].reverse().map(l=>l.id);if(BOX.__subs&&!BOX.__subs.ghost)ids.unshift('__subs');else if(BOX.__subs)ids.push('__subs');const cv=cvs();const ar=cv?cv.width/cv.height:1;
  for(const id of ids){const b=BOX[id];if(!b)continue;const a=-(b.rot||0)*Math.PI/180;const px=(u-b.cx)*ar,py=v-b.cy;const lx=(px*Math.cos(a)-py*Math.sin(a))/ar,ly=px*Math.sin(a)+py*Math.cos(a);
    if(Math.abs(lx)<=b.w/2+0.01&&Math.abs(ly)<=b.h/2+0.01)return id}return null}
