// ---------- preferences ----------
const PNAME={'exp:up':'מעדיף תמונה בהירה יותר','exp:down':'מעדיף תמונה כהה יותר','con:up':'מעדיף ניגודיות גבוהה','con:down':'מעדיף ניגודיות רכה','sat:up':'מעדיף צבעים חיים','sat:down':'מעדיף צבעים טבעיים ופחות רוויים','temp:up':'מעדיף גוון חם','temp:down':'מעדיף גוון קר',
 'subs:smaller':'מעדיף כתוביות קטנות יותר','subs:bigger':'מעדיף כתוביות גדולות יותר','subs:higher':'מעדיף כתוביות גבוהות יותר במסך','subs:lower':'מעדיף כתוביות נמוכות יותר','pace:tighter':'מעדיף קצב מהיר בלי שתיקות','scale:zoom':'מעדיף מסגור קרוב (זום)','overlay:more':'אוהב טקסט וגרפיקה על המסך','enh:on':'מעדיף שיפור דיבור פועל','music:quieter':'מעדיף מוזיקה שקטה יותר','music:duck':'מעדיף שהמוזיקה תרד בזמן דיבור','fx:vignette':'אוהב וינייטה'};
function learn(key,w){if(!PREF.learn||!key)return;(Array.isArray(key)?key:[key]).forEach(k=>{PREF.score[k]=+((PREF.score[k]||0)+w).toFixed(2);const pid=S.p&&S.p.id;if(pid){PREF.proj[pid]=PREF.proj[pid]||{};PREF.proj[pid][k]=+((PREF.proj[pid][k]||0)+w).toFixed(2)}});savePrefs()}
function keysOf(ops,before){const ks=[];const bc=id=>(before.clips||[]).find(c=>c.id===id);ops.forEach(q=>{
  if(q.op==='adjust')(q.clips||[]).forEach(id=>{const c=bc(id);if(!c)return;['exp','con','sat','temp'].forEach(k=>{if(q[k]!=null&&Math.abs(q[k]-c.adj[k])>0.04)ks.push(k+':'+(q[k]>c.adj[k]?'up':'down'))})});
  if(q.op==='subs_set'&&before.subs){if(q.size!=null&&q.size!==before.subs.size)ks.push(q.size<before.subs.size?'subs:smaller':'subs:bigger');if(q.y!=null&&q.y!==before.subs.y)ks.push(q.y<before.subs.y?'subs:higher':'subs:lower');if(q.bg)ks.push('subbg:'+q.bg)}
  if(q.op==='effect'){if(q.look&&q.look!=='none')ks.push('look:'+q.look);if(q.vignette>0.05)ks.push('fx:vignette')}if(q.op==='transition')ks.push('trans:'+q.type);if(q.op==='cut_pauses')ks.push('pace:tighter');if(q.op==='frame'&&q.scale>1.05)ks.push('scale:zoom');if(q.op==='layer_add')ks.push('overlay:more');if(q.op==='enhance_audio'&&q.on)ks.push('enh:on');
  if(q.op==='audio_set'&&q.track!=='orig'){const t=(before.tracks||[]).find(x=>x.id===q.track);if(t&&t.kind==='music'){if(q.vol!=null&&q.vol<t.vol)ks.push('music:quieter');if(q.duck)ks.push('music:duck')}}});return [...new Set(ks)]}
