function rules(){const out=[];Object.entries(PREF.score).forEach(([k,v])=>{if(Math.abs(v)<2)return;let text=PNAME[k]||(k.startsWith('trans:')?'מעברים: '+((TRANS.find(t=>'trans:'+t[0]===k)||[])[1]||k):k.startsWith('subbg:')?'סגנון כתוביות: '+((SUBBG.find(t=>'subbg:'+t[0]===k)||[])[1]||k):k.startsWith('look:')?'מראה: '+((LOOKS.find(t=>'look:'+t[0]===k)||[])[1]||k):k);if(v<0)text='לא אוהב: '+text.replace(/^מעדיף /,'').replace(/^אוהב /,'');out.push({k,v,text,conf:Math.abs(v)>=4?'גבוה':'בינוני'})});return out.sort((a,b)=>Math.abs(b.v)-Math.abs(a.v))}

